mod.css:
section[aria-label="2026 Go Developer Survey"] {
  display: none !important;
}

mod.js:
morse.watch("body div, body section, body aside, body footer", el => {
  const pos = getComputedStyle(el).position;
  if (pos !== "fixed") return;
  const text = el.textContent || "";
  if (/cookie/i.test(text) && text.length < 500) {
    el.style.setProperty("display", "none", "important");
  }
});

mod.css:
body, #content, .banner, .horizontal-section, .project-tabs, .project-tabs__panel, .project-description, .site-header, #sticky-notifications, aside, [class*="sidebar"] { background-color: #0d1117 !important; }
body, #content, .project-tabs, .project-description *:not(a), .site-header *:not(a), aside *:not(a), [class*="sidebar"] *:not(a) { color: #e6edf3 !important; }
#content a, .site-header a, aside a, [class*="sidebar"] a { color: #58a6ff !important; }
#content h1, #content h2, #content h3, .project-description h2 { border-color: #30363d !important; }
pre, code { background-color: #161b22 !important; color: #e6edf3 !important; border-color: #30363d !important; }
#search, input, textarea, select { background-color: #161b22 !important; color: #e6edf3 !important; border-color: #30363d !important; }
button { background-color: #21262d !important; color: #e6edf3 !important; border-color: #30363d !important; }

:root { color-scheme: dark; }

body, .min-h-screen, header, aside, main, .flex-1,
[class*="bg-white"], [class*="bg-neutral-0"], [class*="bg-neutral-1"], [class*="bg-black"] {
  background-color: #0f1115 !important;
}

header, aside, .versions, [class*="bg-white"] { background-color: #171a21 !important; }

body, p, span, div, li, td, th, dt, dd, label, h1, h2, h3, h4, h5, h6,
nav a, aside a, main a, .text-h3, .text-b1, .text-b2, .text-b3, .text-b4, .text-h4 {
  color: #e6e8ec !important;
}

a, a:visited { color: #7cb8ff !important; }
nav a:hover, aside a:hover, main a:hover { color: #b3d7ff !important; }

[class*="border-"], table, th, td, hr, li, ol, ul { border-color: #2c313b !important; }

table, th, td { background-color: transparent !important; }
th { background-color: #1c2029 !important; }

input, textarea, select, #query {
  background-color: #1c2029 !important;
  color: #e6e8ec !important;
  border-color: #2c313b !important;
}
input::placeholder, textarea::placeholder { color: #8a909c !important; }

pre, code, [class*="bg-neutral-1"] {
  background-color: #1c2029 !important;
  color: #e6e8ec !important;
}

button, [class*="bg-neutral-9"], [class*="bg-neutral-8"] {
  color: #0f1115 !important;
}
